    if n == 0:
        return 3
    elif n == 1:
        return 3
    elif n == 2:
        return 5

    # Generate Perrin numbers up to the nth index
    perrin = [3, 0, 2]
    for i in range(3, n + 1):
        if i - 2 >= 0 and i - 3 >= 0:
            next_value = perrin[i - 2] + perrin[i - 3]
        elif i - 2 >= 0:
            next_value = perrin[i - 2]
        else:
            next_value = 0
        perrin.append(next_value)

    # Calculate the sum of Perrin numbers
