def add_pairwise(t):
    # Ensure the tuple has at least two elements to perform pairwise addition
    if len(t) < 2:
        return ()

    # Initialize the result list with the sum of the first two elements
    result = [t[0] + t[1]]

    # Iterate through the tuple and add the pairwise sums
    for i in range(1, len(t) - 1):
        result.append(t[i] + t[i + 1])

    return tuple(result)

